# -*- coding: utf-8 -*-
"""Dokkai N2 v2 — paket 1–10. Susunan (17 soal): 4 短文 (1) + 2 中文 (3+3) + 統合理解 A/B (2) + 主張理解 (3) + 情報検索 (2)."""
T, C, I, S, J = ("Teks pendek (内容理解・短文)", "Teks menengah (内容理解・中文)", "Bacaan gabungan (統合理解)",
                 "Teks panjang / opini (主張理解・長文)", "Mencari informasi (情報検索)")


def tbl(head, rows):
    h = "".join(f"<th>{x}</th>" for x in head)
    b = "".join("<tr>" + "".join(f"<td>{x}</td>" for x in r) + "</tr>" for r in rows)
    return f"<table class='jx-table'><tr>{h}</tr>{b}</table>"


